-- 서울시 주요 121장소 영역 Shapefile 기반 기준정보
-- 원본 좌표계: GCS_WGS_1984 / WGS84
-- 대상 스키마: doc/투어스위치_DB설계.md 의 seoul_realtime_area

AS incoming
ON DUPLICATE KEY UPDATE
    area_name = incoming.area_name,
    category = incoming.category,
    latitude = incoming.latitude,
    longitude = incoming.longitude,
    boundary = incoming.boundary;



